//! FROZEN manager table, #2361. Coders/reviewers do not edit this file.
use super::{ConsoleTypeOutcome as O, ConsoleTypePlan, ConsoleTypeRefusal as R, ReceiverIdentity};

const A: ReceiverIdentity = (101, 202, 303);

struct Row {
    name: &'static str,
    session: Option<&'static str>,
    owner: Option<&'static str>,
    target: Option<i64>,
    claimed: bool,
    class: &'static str,
    saved: Option<ReceiverIdentity>,
    observed: Option<ReceiverIdentity>,
    text: String,
    coordinates: bool,
    expected: Result<Vec<u16>, R>,
}

impl Row {
    fn normal(name: &'static str) -> Self {
        Self {
            name,
            session: Some("A"),
            owner: Some("A"),
            target: Some(101),
            claimed: true,
            class: "ConsoleWindowClass",
            saved: Some(A),
            observed: Some(A),
            text: "a".to_owned(),
            coordinates: false,
            expected: Ok(vec![0x61]),
        }
    }
}

fn rows() -> Vec<Row> {
    let mut rows = Vec::new();
    macro_rules! row {
        ($name:literal, $field:ident = $value:expr, $expected:expr) => {{
            let mut row = Row::normal($name);
            row.$field = $value;
            row.expected = $expected;
            rows.push(row);
        }};
    }
    rows.push(Row::normal("T_L01_ascii"));
    row!(
        "T_L02_unicode",
        text = "שΩ🙂".to_owned(),
        Ok(vec![0x05e9, 0x03a9, 0xd83d, 0xde42])
    );
    row!("T_L03_space", text = " ".to_owned(), Ok(vec![0x20]));
    row!(
        "T_L04_limit",
        text = "a".repeat(65_536),
        Ok(vec![0x61; 65_536])
    );
    row!("T_L05_empty", text = String::new(), Err(R::Empty));
    row!("T_L06_cr", text = "a\rb".to_owned(), Err(R::Control));
    row!("T_L07_lf", text = "a\nb".to_owned(), Err(R::Control));
    row!("T_L08_nul", text = "a\0b".to_owned(), Err(R::Control));
    row!("T_L09_tab", text = "a\tb".to_owned(), Err(R::Control));
    row!(
        "T_L10_escape",
        text = "\u{1b}[2J".to_owned(),
        Err(R::Control)
    );
    row!(
        "T_L11_oversize",
        text = "a".repeat(65_537),
        Err(R::TooLarge)
    );
    row!("T_L12_no_session", session = None, Err(R::Session));
    row!("T_L13_blank_session", session = Some(" "), Err(R::Session));
    row!("T_L14_other_actor", session = Some("B"), Err(R::Ownership));
    row!("T_L15_no_launch", owner = None, Err(R::Ownership));
    row!("T_L16_no_target", target = None, Err(R::Target));
    row!("T_L17_wrong_target", target = Some(404), Err(R::Identity));
    row!("T_L18_no_claim", claimed = false, Err(R::Claim));
    row!(
        "T_L19_terminal",
        class = "CASCADIA_HOSTING_WINDOW_CLASS",
        Err(R::Class)
    );
    row!("T_L20_code", class = "Chrome_WidgetWin_1", Err(R::Class));
    row!(
        "T_L21_class_case",
        class = "consolewindowclass",
        Err(R::Class)
    );
    row!("T_L22_missing_saved", saved = None, Err(R::Identity));
    row!("T_L23_closed", observed = None, Err(R::Identity));
    row!(
        "T_L24_reused_pid",
        observed = Some((101, 202, 304)),
        Err(R::Identity)
    );
    row!(
        "T_L25_reused_hwnd",
        observed = Some((101, 405, 303)),
        Err(R::Identity)
    );
    row!(
        "T_L26_zero_pid",
        saved = Some((101, 0, 303)),
        Err(R::Identity)
    );
    row!(
        "T_L27_zero_birth",
        saved = Some((101, 202, 0)),
        Err(R::Identity)
    );
    row!("T_L28_restart", owner = None, Err(R::Ownership));
    row!("T_L29_negative_target", target = Some(-1), Err(R::Target));
    row!(
        "T_L36_surrogate_limit",
        text = "🙂".repeat(32_768),
        Ok([0xd83d, 0xde42].repeat(32_768))
    );
    row!(
        "T_L37_surrogate_oversize",
        text = "🙂".repeat(32_769),
        Err(R::TooLarge)
    );
    row!("T_L38_cdp_target", target = None, Err(R::Target));
    row!("T_L44_coordinates", coordinates = true, Err(R::Coordinates));
    rows
}

fn check(name: &str) {
    let row = match rows().into_iter().find(|row| row.name == name) {
        Some(row) => row,
        None => panic!("missing frozen row {name}"),
    };
    let actual = ConsoleTypePlan::new(
        row.session,
        row.owner,
        row.target,
        row.claimed,
        row.class,
        row.saved,
        row.observed,
        &row.text,
        row.coordinates,
    )
    .map(|plan| (plan.identity(), plan.key_records()));
    let expected = row.expected.map(|units| {
        (
            A,
            units
                .into_iter()
                .flat_map(|unit| [(true, unit), (false, unit)])
                .collect::<Vec<_>>(),
        )
    });
    assert_eq!(actual, expected, "{name}");
}

fn confirm(observed: Option<ReceiverIdentity>, clients: &[u32], expected: Result<(), R>) {
    let plan = match ConsoleTypePlan::new(
        Some("A"),
        Some("A"),
        Some(101),
        true,
        "ConsoleWindowClass",
        Some(A),
        Some(A),
        "a",
        false,
    ) {
        Ok(plan) => plan,
        Err(error) => panic!("valid receiver fixture refused: {error:?}"),
    };
    assert_eq!(plan.confirm_receiver(observed, clients), expected);
}

macro_rules! pure_row { ($($name:ident),+ $(,)?) => { $(#[test] fn $name() { check(stringify!($name)); })+ }; }
