fn outcome(code: Option<i32>, expected: O) {
    let plan = match ConsoleTypePlan::new(
        Some("A"),
        Some("A"),
        Some(101),
        true,
        "ConsoleWindowClass",
        Some(A),
        Some(A),
        "שΩ🙂",
        false,
    ) {
        Ok(plan) => plan,
        Err(error) => panic!("valid outcome fixture refused: {error:?}"),
    };
    assert_eq!(plan.helper_outcome(code), expected);
}

